	"002-implement-function/grade.mjs": "// Hidden grader for 002-implement-function. Visible cases + extra edge cases\n// the agent never sees (anti-overfit).\nimport assert from \"node:assert/strict\";\nimport { spawnSync } from \"node:child_process\";\nimport fs from \"node:fs\";\nimport path from \"node:path\";\nimport { pathToFileURL } from \"node:url\";\n\n// The agent must not touch test.mjs.\nconst testSrc = fs.readFileSync(\"test.mjs\", \"utf8\");\nconst testUntouched = testSrc.includes('[\"Hello World\", \"hello-world\"]');\n\nconst visible = spawnSync(process.execPath, [\"test.mjs\"], { encoding: \"utf8\", timeout: 15000 });\n\nconst hiddenFailures = [];\nconst extra = [\n\t[\"A--B\", \"a-b\"], // hyphen runs collapse\n\t[\"-leading and trailing-\", \"leading-and-trailing\"],\n\t[\"Ærøskøbing 42\", \"rskbing-42\"], // multi-char accents stripped to ASCII\n\t[\"123 456\", \"123-456\"],\n];\n\nlet mod = null;\ntry {\n\t// Import from the agent's repo copy (the grader's cwd), not this file's dir.\n\tmod = await import(pathToFileURL(path.join(process.cwd(), \"lib\", \"slugify.js\")).href);\n} catch {\n\tmod = null;\n}\n\nif (mod && typeof mod.slugify === \"function\") {\n\tfor (const [input, expected] of extra) {\n\t\ttry {\n\t\t\tassert.equal(mod.slugify(input), expected);\n\t\t} catch {\n\t\t\thiddenFailures.push(`${JSON.stringify(input)} -> ${JSON.stringify(mod.slugify(input))}, expected ${JSON.stringify(expected)}`);\n\t\t}\n\t}\n} else {\n\thiddenFailures.push(\"lib/slugify.js does not export slugify\");\n}\n\nconst pass = testUntouched && visible.status === 0 && hiddenFailures.length === 0;\n\nconsole.log(\n\tJSON.stringify({\n\t\tpass,\n\t\tvisibleTests: visible.status === 0 ? \"pass\" : `fail: ${(visible.stdout ?? \"\").trim().slice(0, 200)}`,\n\t\thiddenFailures,\n\t\ttestFileUntouched: testUntouched,\n\t}),\n);\nprocess.exit(pass ? 0 : 1);",
	"002-implement-function/repo/lib/slugify.js": "/**\n * Convert a title into a URL slug:\n * - lowercase\n * - spaces and underscores become single hyphens\n * - accented characters are transliterated to ASCII (e.g. é -> e)\n * - characters other than a-z, 0-9, and hyphens are removed\n * - runs of hyphens collapse to one; leading/trailing hyphens are trimmed\n *\n * Examples:\n *   slugify(\"Hello World\")        === \"hello-world\"\n *   slugify(\"  Multiple   Spaces \") === \"multiple-spaces\"\n *   slugify(\"Hello_World\")        === \"hello-world\"\n *   slugify(\"Café & Bar!\")        === \"cafe-bar\"\n *   slugify(\"\")                   === \"\"\n *\n * @param {string} title\n * @returns {string}\n */\nexport function slugify(title) {\n\t// TODO: implement\n\treturn title;\n}",
	"002-implement-function/repo/test.mjs": "import assert from \"node:assert/strict\";\nimport { slugify } from \"./lib/slugify.js\";\n\nconst cases = [\n\t[\"Hello World\", \"hello-world\"],\n\t[\"  Multiple   Spaces  \", \"multiple-spaces\"],\n\t[\"Hello_World\", \"hello-world\"],\n\t[\"Café & Bar!\", \"cafe-bar\"],\n];\n\nlet failed = 0;\nfor (const [input, expected] of cases) {\n\ttry {\n\t\tassert.equal(slugify(input), expected);\n\t} catch (err) {\n\t\tfailed++;\n\t\tconsole.error(`FAIL slugify(${JSON.stringify(input)}) => ${JSON.stringify(slugify(input))}, expected ${JSON.stringify(expected)}`);\n\t}\n}\nif (failed > 0) {\n\tconsole.error(`${failed}/${cases.length} failed`);\n\tprocess.exit(1);\n}\nconsole.log(`all ${cases.length} cases pass`);",
