	"003-fix-off-by-one/grade.mjs": "// Hidden grader for 003-fix-off-by-one. No test file ships in the repo; the\n// whole contract lives here.\nimport assert from \"node:assert/strict\";\nimport path from \"node:path\";\nimport { pathToFileURL } from \"node:url\";\n\nconst failures = [];\nconst check = (name, fn) => {\n\ttry {\n\t\tfn();\n\t} catch (err) {\n\t\tfailures.push(`${name}: ${err instanceof Error ? err.message.slice(0, 200) : String(err)}`);\n\t}\n};\n\nlet mod = null;\ntry {\n\t// Import from the agent's repo copy (the grader's cwd), not this file's dir.\n\tmod = await import(pathToFileURL(path.join(process.cwd(), \"lib\", \"pager.js\")).href);\n} catch {\n\tfailures.push(\"lib/pager.js does not import\");\n}\n\nif (mod && typeof mod.pageItems === \"function\") {\n\tconst items = [\"a\", \"b\", \"c\", \"d\", \"e\", \"f\", \"g\", \"h\", \"i\", \"j\", \"k\", \"l\"];\n\tconst { pageItems } = mod;\n\tcheck(\"page 1\", () => assert.deepEqual(pageItems(items, 1, 5), [\"a\", \"b\", \"c\", \"d\", \"e\"]));\n\tcheck(\"page 2\", () => assert.deepEqual(pageItems(items, 2, 5), [\"f\", \"g\", \"h\", \"i\", \"j\"]));\n\tcheck(\"page 3 partial\", () => assert.deepEqual(pageItems(items, 3, 5), [\"k\", \"l\"]));\n\tcheck(\"page 4 beyond last\", () => assert.deepEqual(pageItems(items, 4, 5), []));\n\tcheck(\"page 99 far beyond\", () => assert.deepEqual(pageItems(items, 99, 5), []));\n\tcheck(\"pageSize larger than list\", () => assert.deepEqual(pageItems(items, 1, 50), items));\n\tcheck(\"empty list\", () => assert.deepEqual(pageItems([], 1, 5), []));\n\tcheck(\"single item list\", () => assert.deepEqual(pageItems([\"x\"], 1, 1), [\"x\"]));\n\tcheck(\"does not mutate input\", () => {\n\t\tconst input = [\"a\", \"b\", \"c\"];\n\t\tpageItems(input, 1, 2);\n\t\tassert.deepEqual(input, [\"a\", \"b\", \"c\"]);\n\t});\n} else if (failures.length === 0) {\n\tfailures.push(\"pageItems export missing\");\n}\n\nconst pass = failures.length === 0;\nconsole.log(JSON.stringify({ pass, failures }));\nprocess.exit(pass ? 0 : 1);",
	"003-fix-off-by-one/repo/lib/pager.js": "/**\n * Return the items for a 1-based page.\n *\n * @param {string[]} items full list\n * @param {number} page 1-based page number\n * @param {number} pageSize items per page\n * @returns {string[]} the slice for that page; empty array if the page is\n *   beyond the last page\n */\nexport function pageItems(items, page, pageSize) {\n\tconst start = page * pageSize + 1;\n\treturn items.slice(start, start + pageSize);\n}",
	"003-fix-off-by-one/repo/main.js": "import { pageItems } from \"./lib/pager.js\";\n\nconst alphabet = [\"a\", \"b\", \"c\", \"d\", \"e\", \"f\", \"g\", \"h\", \"i\", \"j\", \"k\", \"l\"];\n\nconsole.log(\"page 1:\", JSON.stringify(pageItems(alphabet, 1, 5)));\nconsole.log(\"page 2:\", JSON.stringify(pageItems(alphabet, 2, 5)));\nconsole.log(\"page 3:\", JSON.stringify(pageItems(alphabet, 3, 5)));\nconsole.log(\"page 4:\", JSON.stringify(pageItems(alphabet, 4, 5)));",
	"003-fix-off-by-one/task.json": "{\n\t\"id\": \"003-fix-off-by-one\",\n\t\"title\": \"Fix pager off-by-one\",\n\t\"instruction\": \"`pageItems` in lib/pager.js returns the wrong slice of items. Pages are 1-based: page 1 returns the first `pageSize` items, page 2 the next `pageSize`, and so on. Requesting a page beyond the last page returns an empty array. Fix the function so it follows that contract. Run `node main.js` to see the demo output.\",\n\t\"tags\": [\"bugfix\", \"logic\", \"hidden-tests\"],\n\t\"timeoutSeconds\": 300,\n\t\"grader\": \"grade.mjs\"\n}",
	"004-precise-json-edit/grade.mjs": "// Hidden grader for 004-precise-json-edit: exact structural equality with the\n// expected final config - catches both under-editing and collateral changes.\nimport assert from \"node:assert/strict\";\nimport fs from \"node:fs\";\n\nconst expected = {\n\tname: \"acme-backend\",\n\tversion: \"1.4.2\",\n\tservices: {\n\t\tauth: { port: 3000, retries: 0, upstream: \"internal-auth:9000\" },\n\t\tpayments: { port: 8443, retries: { count: 3, backoff: \"exponential\" }, upstream: \"billing-core:7000\" },\n\t\tsearch: { port: 9200, retries: 0, upstream: \"indexer:9200\" },\n\t},\n\tfeatures: { darkMode: true, betaSearch: false },\n};\n\nconst failures = [];\nlet actual = null;\ntry {\n\tactual = JSON.parse(fs.readFileSync(\"config.json\", \"utf8\"));\n} catch (err) {\n\tfailures.push(`config.json does not parse: ${err instanceof Error ? err.message.slice(0, 120) : String(err)}`);\n}\n\nif (actual) {\n\tcheck(\"deep equality with expected config\", () => assert.deepEqual(actual, expected));\n\tconst raw = fs.readFileSync(\"config.json\", \"utf8\");\n\tcheck(\"payments.retries is an object\", () => {\n\t\tconst parsed = JSON.parse(raw);\n\t\tassert.equal(typeof parsed.services.payments.retries, \"object\");\n\t});\n\tcheck(\"indentation preserved (2-space)\", () => assert.ok(raw.includes('\\n  \"name\"'), \"expected 2-space indent\"));\n}\n\nfunction check(name, fn) {\n\ttry {\n\t\tfn();\n\t} catch (err) {\n\t\tfailures.push(`${name}: ${err instanceof Error ? err.message.slice(0, 300) : String(err)}`);\n\t}\n}\n\nconst pass = failures.length === 0;\nconsole.log(JSON.stringify({ pass, failures }));\nprocess.exit(pass ? 0 : 1);",
	"004-precise-json-edit/repo/config.json": "{\n  \"name\": \"acme-backend\",\n  \"version\": \"1.4.2\",\n  \"services\": {\n    \"auth\": {\n      \"port\": 3000,\n      \"retries\": 0,\n      \"upstream\": \"internal-auth:9000\"\n    },\n    \"payments\": {\n      \"port\": 8080,\n      \"retries\": 0,\n      \"upstream\": \"billing-core:7000\"\n    },\n    \"search\": {\n      \"port\": 9200,\n      \"retries\": 0,\n      \"upstream\": \"indexer:9200\"\n    }\n  },\n  \"features\": {\n    \"darkMode\": true,\n    \"betaSearch\": false\n  }\n}",
