	"005-refactor-extract/grade.mjs": "// Hidden grader for 005-refactor-extract: behavior preserved + the extraction\n// actually happened (new module exists, reports.js imports it).\nimport assert from \"node:assert/strict\";\nimport { spawnSync } from \"node:child_process\";\nimport fs from \"node:fs\";\nimport path from \"node:path\";\nimport { pathToFileURL } from \"node:url\";\n\nconst failures = [];\nconst check = (name, fn) => {\n\ttry {\n\t\tfn();\n\t} catch (err) {\n\t\tfailures.push(`${name}: ${err instanceof Error ? err.message.slice(0, 250) : String(err)}`);\n\t}\n};\n\n// 1. Behavior: demo output unchanged.\nconst run = spawnSync(process.execPath, [\"main.js\"], { encoding: \"utf8\", timeout: 15000 });\ncheck(\"main.js runs clean\", () => assert.equal(run.status, 0));\nconst expectedOutput = [\n\t\"weekly: 2 events (2026-01-01T00:00:00.000Z .. 2026-01-31T23:59:59.999Z)\",\n\t\"monthly: 1 events (2026-02-01T00:00:00.000Z .. 2026-02-28T23:59:59.999Z)\",\n\t\"quarterly: 4 events (2026-01-01T00:00:00.000Z .. 2026-03-15T23:59:59.999Z)\",\n\t\"weekly: 4 events (beginning .. now)\",\n];\ncheck(\"demo output unchanged\", () => assert.deepEqual((run.stdout ?? \"\").trim().split(\"\\n\"), expectedOutput));\n\n// 2. The extraction exists and behaves.\nlet dr = null;\ntry {\n\t// Import from the agent's repo copy (the grader's cwd), not this file's dir.\n\tdr = await import(pathToFileURL(path.join(process.cwd(), \"lib\", \"dateRange.js\")).href);\n} catch {\n\tfailures.push(\"lib/dateRange.js missing or does not import\");\n}\nif (dr && typeof dr.clampDateRange === \"function\") {\n\tcheck(\"clampDateRange basic\", () => {\n\t\tconst r = dr.clampDateRange(\"2026-01-01\", \"2026-01-31\");\n\t\tassert.deepEqual(Object.keys(r).sort(), [\"end\", \"start\"]);\n\t\tassert.equal(r.start, \"2026-01-01T00:00:00.000Z\");\n\t\tassert.equal(r.end, \"2026-01-31T23:59:59.999Z\");\n\t});\n\tcheck(\"clampDateRange swaps reversed range\", () => {\n\t\tconst r = dr.clampDateRange(\"2026-03-01\", \"2026-01-01\");\n\t\tassert.equal(r.start, \"2026-01-01T00:00:00.000Z\");\n\t\tassert.equal(r.end, \"2026-03-01T23:59:59.999Z\");\n\t});\n\tcheck(\"clampDateRange handles nulls\", () => {\n\t\tconst r = dr.clampDateRange(null, null);\n\t\tassert.equal(r.start, null);\n\t\tassert.equal(r.end, null);\n\t});\n} else if (failures.length === 0) {\n\tfailures.push(\"clampDateRange export missing from lib/dateRange.js\");\n}\n\n// 3. The refactor actually wired through: reports.js references dateRange.\ncheck(\"reports.js uses the new module\", () => {\n\tconst src = fs.readFileSync(\"lib/reports.js\", \"utf8\");\n\tassert.ok(src.includes(\"dateRange\"), \"reports.js should import lib/dateRange.js\");\n});\n\nconst pass = failures.length === 0;\nconsole.log(JSON.stringify({ pass, failures }));\nprocess.exit(pass ? 0 : 1);",
	"005-refactor-extract/repo/lib/reports.js": "/**\n * Report generators. Each clamps an optional date range to valid ISO bounds\n * and produces a labeled report line.\n */\n\nfunction startOfDayIso(iso) {\n\tconst d = new Date(iso);\n\td.setUTCHours(0, 0, 0, 0);\n\treturn d.toISOString();\n}\n\nfunction endOfDayIso(iso) {\n\tconst d = new Date(iso);\n\td.setUTCHours(23, 59, 59, 999);\n\treturn d.toISOString();\n}\n\nexport function weeklyReport(startIso, endIso, events) {\n\tlet start = startIso;\n\tlet end = endIso;\n\tif (start && end && new Date(start) > new Date(end)) {\n\t\t[start, end] = [end, start];\n\t}\n\tif (start) start = startOfDayIso(start);\n\tif (end) end = endOfDayIso(end);\n\tconst filtered = events.filter((e) => (!start || e.t >= start) && (!end || e.t <= end));\n\treturn `weekly: ${filtered.length} events (${start ?? \"beginning\"} .. ${end ?? \"now\"})`;\n}\n\nexport function monthlyReport(startIso, endIso, events) {\n\tlet start = startIso;\n\tlet end = endIso;\n\tif (start && end && new Date(start) > new Date(end)) {\n\t\t[start, end] = [end, start];\n\t}\n\tif (start) start = startOfDayIso(start);\n\tif (end) end = endOfDayIso(end);\n\tconst filtered = events.filter((e) => (!start || e.t >= start) && (!end || e.t <= end));\n\treturn `monthly: ${filtered.length} events (${start ?? \"beginning\"} .. ${end ?? \"now\"})`;\n}\n\nexport function quarterlyReport(startIso, endIso, events) {\n\tlet start = startIso;\n\tlet end = endIso;\n\tif (start && end && new Date(start) > new Date(end)) {\n\t\t[start, end] = [end, start];\n\t}\n\tif (start) start = startOfDayIso(start);\n\tif (end) end = endOfDayIso(end);\n\tconst filtered = events.filter((e) => (!start || e.t >= start) && (!end || e.t <= end));\n\treturn `quarterly: ${filtered.length} events (${start ?? \"beginning\"} .. ${end ?? \"now\"})`;\n}",
	"005-refactor-extract/repo/main.js": "import { weeklyReport, monthlyReport, quarterlyReport } from \"./lib/reports.js\";\n\nconst events = [\n\t{ t: \"2026-01-05T10:00:00.000Z\", label: \"deploy\" },\n\t{ t: \"2026-01-20T12:00:00.000Z\", label: \"incident\" },\n\t{ t: \"2026-02-10T08:30:00.000Z\", label: \"release\" },\n\t{ t: \"2026-03-01T16:00:00.000Z\", label: \"audit\" },\n];\n\nconsole.log(weeklyReport(\"2026-01-01\", \"2026-01-31\", events));\nconsole.log(monthlyReport(\"2026-02-01\", \"2026-02-28\", events));\nconsole.log(quarterlyReport(\"2026-03-15\", \"2026-01-01\", events)); // reversed on purpose\nconsole.log(weeklyReport(null, null, events));",
	"005-refactor-extract/task.json": "{\n\t\"id\": \"005-refactor-extract\",\n\t\"title\": \"Extract duplicated date-range clamping\",\n\t\"instruction\": \"In lib/reports.js, the date range clamping logic is duplicated in three functions (weeklyReport, monthlyReport, quarterlyReport). Extract it into a new exported function `clampDateRange(startIso, endIso)` in a new file `lib/dateRange.js` that returns `{ start, end }` as ISO strings, and use it from all three functions. All existing behavior must be preserved - run `node main.js` to verify the demo output stays the same.\",\n\t\"tags\": [\"refactor\", \"architecture\"],\n\t\"timeoutSeconds\": 360,\n\t\"grader\": \"grade.mjs\"\n}"
